// OrganizationsServiceHandler is an implementation of the organizations.v1.OrganizationsService
// service.
type OrganizationsServiceHandler interface {
	// User's organizations
	ListMyOrganizations(context.Context, *connect.Request[v1.ListMyOrganizationsRequest]) (*connect.Response[v1.ListMyOrganizationsResponse], error)
	// Finds which of the caller's own organizations owns the content behind a
	// URN. Unknown content, content the caller cannot view, and content outside
	// the caller's memberships all return the same NOT_FOUND error.
	ResolveContentOrganization(context.Context, *connect.Request[v1.ResolveContentOrganizationRequest]) (*connect.Response[v1.ResolveContentOrganizationResponse], error)
	// Self-service creation. Allowed when the deployment's org_creation policy
	// admits the caller; the caller becomes OWNER. Rate limited per user and IP.
	CreateOrganization(context.Context, *connect.Request[v1.CreateOrganizationRequest]) (*connect.Response[v1.CreateOrganizationResponse], error)
	// Invitations addressed to the caller's email, and the signed-in way to act on them.
	ListMyInvitations(context.Context, *connect.Request[v1.ListMyInvitationsRequest]) (*connect.Response[v1.ListMyInvitationsResponse], error)
	AcceptMyInvitation(context.Context, *connect.Request[v1.AcceptMyInvitationRequest]) (*connect.Response[v1.AcceptMyInvitationResponse], error)
	DeclineMyInvitation(context.Context, *connect.Request[v1.DeclineMyInvitationRequest]) (*connect.Response[v1.DeclineMyInvitationResponse], error)
	// Organization read/update (Org Member / Org Admin). Cross-tenant CRUD
	// is the platform surface: superadmin.v1.SystemOrganizationsService.
	GetOrganization(context.Context, *connect.Request[v1.GetOrganizationRequest]) (*connect.Response[v1.GetOrganizationResponse], error)
	UpdateOrganization(context.Context, *connect.Request[v1.UpdateOrganizationRequest]) (*connect.Response[v1.UpdateOrganizationResponse], error)
	// Membership lifecycle for the caller's own place in the organization.
	// An OWNER transfers before leaving; deletion is OWNER only and soft, with
	// the same purge window the platform surface applies.
	LeaveOrganization(context.Context, *connect.Request[v1.LeaveOrganizationRequest]) (*connect.Response[v1.LeaveOrganizationResponse], error)
	TransferOwnership(context.Context, *connect.Request[v1.TransferOwnershipRequest]) (*connect.Response[v1.TransferOwnershipResponse], error)
	DeleteOrganization(context.Context, *connect.Request[v1.DeleteOrganizationRequest]) (*connect.Response[v1.DeleteOrganizationResponse], error)
	// Organization overview (Org Admin)
	GetOrganizationOverview(context.Context, *connect.Request[v1.GetOrganizationOverviewRequest]) (*connect.Response[v1.GetOrganizationOverviewResponse], error)
	// Member management (Org Admin)
	ListMembers(context.Context, *connect.Request[v1.ListMembersRequest]) (*connect.Response[v1.ListMembersResponse], error)
	AddMember(context.Context, *connect.Request[v1.AddMemberRequest]) (*connect.Response[v1.AddMemberResponse], error)
	UpdateMemberRole(context.Context, *connect.Request[v1.UpdateMemberRoleRequest]) (*connect.Response[v1.UpdateMemberRoleResponse], error)
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
	InviteMember(context.Context, *connect.Request[v1.InviteMemberRequest]) (*connect.Response[v1.InviteMemberResponse], error)
	ListInvitations(context.Context, *connect.Request[v1.ListInvitationsRequest]) (*connect.Response[v1.ListInvitationsResponse], error)
	RevokeInvitation(context.Context, *connect.Request[v1.RevokeInvitationRequest]) (*connect.Response[v1.RevokeInvitationResponse], error)
	ResendInvitation(context.Context, *connect.Request[v1.ResendInvitationRequest]) (*connect.Response[v1.ResendInvitationResponse], error)
	GetSecuritySettings(context.Context, *connect.Request[v1.GetSecuritySettingsRequest]) (*connect.Response[v1.GetSecuritySettingsResponse], error)
	UpdateSecuritySettings(context.Context, *connect.Request[v1.UpdateSecuritySettingsRequest]) (*connect.Response[v1.UpdateSecuritySettingsResponse], error)
	// Permission defaults (Org Admin)
	GetPermissionDefaults(context.Context, *connect.Request[v1.GetPermissionDefaultsRequest]) (*connect.Response[v1.GetPermissionDefaultsResponse], error)
	UpdatePermissionDefaults(context.Context, *connect.Request[v1.UpdatePermissionDefaultsRequest]) (*connect.Response[v1.UpdatePermissionDefaultsResponse], error)
	// Domain Admin management (Org Admin)
	GrantDomainAdmin(context.Context, *connect.Request[v1.GrantDomainAdminRequest]) (*connect.Response[v1.GrantDomainAdminResponse], error)
	RevokeDomainAdmin(context.Context, *connect.Request[v1.RevokeDomainAdminRequest]) (*connect.Response[v1.RevokeDomainAdminResponse], error)
	ListDomainAdmins(context.Context, *connect.Request[v1.ListDomainAdminsRequest]) (*connect.Response[v1.ListDomainAdminsResponse], error)
	GetUserDomainAdmins(context.Context, *connect.Request[v1.GetUserDomainAdminsRequest]) (*connect.Response[v1.GetUserDomainAdminsResponse], error)
	// Encryption key rotation (Org Owner only). Generates a fresh Data
	// Encryption Key for the organization, re-encrypts every secret under
	// it, and retires the previous key.
	RotateEncryptionKey(context.Context, *connect.Request[v1.RotateEncryptionKeyRequest]) (*connect.Response[v1.RotateEncryptionKeyResponse], error)
}

